(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zt-sj-prepa-chir-j5-ide"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zt-sj-prepa-chir-j5-ide\",\n \"titre\": \"Préparation D.E (J) · J5 Chirurgie IDE\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 60,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J5_Chirurgie_IDE_corrige_explique.pdf\",\n   \"sha256\": \"c1f40b708ea0eef1de134c3e4a909eb347076ccf1e47e65b95e681638ca45148\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Chirurgie · Prépa D.E J5 (IDE)\",\n     \"slug\": \"prepa-chir-j5-ide\",\n     \"pages\": \"\",\n     \"count\": 60,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Chirurgie\",\n     \"source\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un patient présentant plusieurs fractures est obligatoirement un polytraumatisé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le polytraumatisé présente plusieurs traumatismes à des endroits différents dont au moins un met en jeu le pronostic vital. Le cours insiste : « il ne faut pas confondre polytraumatisé avec poly-fracturé ». Plusieurs fractures sans menace vitale = polyfracturé, donc l'affirmation est fausse.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), « Le polytraumatisé », p. 86 ; Cours de chirurgie traumatique et digestif (pptx), diapo 144\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une entorse correspond à une lésion ligamentaire sans perte permanente du contact entre les surfaces articulaires\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'entorse est une lésion ligamentaire (élongation, rupture partielle ou totale) sans déplacement permanent des surfaces articulaires ; la perte de contact permanente définit la luxation.\\n\\nSource : ARTHROLOGIE COMPLET, vocabulaire (entorse) ; Pathologie chirurgicale – Sémiologie L1 IDE-SF, luxation p. 73\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans une hernie étranglée, la tuméfaction est habituellement douloureuse, dure, irréductible et non impulsive à la toux\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Signes physiques de l'étranglement herniaire : tuméfaction devenue dure, tendue, douloureuse (maximum au collet), irréductible, non impulsive et non expansive à la toux.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Hernies – étranglement herniaire, p. 107-108\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La cryptorchidie correspond à l'absence d'un ou des deux testicules dans les bourses par défaut de migration\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La cryptorchidie (« testicule caché ») est une anomalie de la descente du testicule dans la bourse, unique ou bilatérale ; le diagnostic repose sur la vacuité de la bourse.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Anomalies de la descente du testicule, p. 182-183 ; Cours de chirurgie traumatique et digestif (pptx), diapo 318\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'hydrocèle correspond à un épanchement liquidien entre les feuillets de la vaginale testiculaire\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'hydrocèle est un épanchement liquidien séreux entre les deux feuillets de la vaginale (signe capital : impossibilité de « pincer » la vaginale, transillumination positive).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), L'hydrocèle, p. 184-185 ; Cours de chirurgie traumatique et digestif (pptx), diapo 321\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La colostomie est l'abouchement temporaire ou définitif d'un segment du côlon à la peau\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La colostomie est l'abouchement chirurgical du côlon à la peau (anus artificiel), temporaire ou définitif. Le cours cite les « soins de colostomie ou anus artificiel » et la possibilité de « mettre provisoirement l'un des deux segments à la peau » après exérèse colique.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), programme de l'UE et Occlusions (traitement), p. 3 et 127 – définition complétée (explication partiellement hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le ramassage d'un traumatisé du rachis doit se faire en monobloc avec maintien de l'axe tête-cou-tronc\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le blessé du rachis se relève en traction axiale, rachis cervical en rectitude, sur un plan dur ; un déplacement monobloc maintient l'axe cranio-rachidien en rectitude. Il ne faut jamais l'empoigner sous les aisselles et les genoux (risque de section médullaire).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), CAT auprès d'un traumatisé des voies publiques, p. 82 ; Neurochirurgie (fascicule), p. 43 et 52\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ponction sus-pubienne peut être indiquée lorsque le sondage urétral est impossible ou contre-indiqué\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le drainage vésical d'une rétention est une urgence : sondage urétral, ou ponction sus-pubienne. « Si le sondage vésical est impossible, il faut pratiquer une ponction sus-pubienne » avec asepsie rigoureuse.\\n\\nSource : Cours de chirurgie traumatique et digestif (pptx), Rétention urinaire et Rétrécissement de l'urètre, diapos 307 et 317\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les vibrations vocales sont appréciées principalement par l'inspection du thorax\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les vibrations vocales s'apprécient à la palpation du thorax, pas à l'inspection. L'inspection apprécie la coloration, le rythme respiratoire, les lésions cutanées et les déformations.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Traumatisme du thorax, p. 8-9 ; Traumatologie complet, examen clinique du thorax\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le pied bot est une malformation pouvant être présente dès la naissance\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le pied bot congénital est un vice de position du pied constaté à la naissance (le varus équin représente 9/10 des cas).\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 IDE-SF, Pieds bots congénitaux, p. 81\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une agénésie d'un membre est une affection congénitale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'agénésie est l'absence de formation d'un organe ou d'un membre pendant le développement embryonnaire : c'est donc une malformation congénitale, présente dès la naissance.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La subluxation correspond à une perte incomplète du contact entre deux surfaces articulaires\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La luxation est dite complète lorsqu'il n'y a plus de rapport entre les deux surfaces articulaires ; s'il reste un contact partiel, il s'agit d'une subluxation (luxation incomplète).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Luxation de l'épaule – généralités, p. 17 ; Traumatologie complet, chap. III\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La tétraplégie correspond à la paralysie des quatre membres\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La tétraplégie est la paralysie des quatre membres (supérieurs et inférieurs), par atteinte médullaire cervicale ; la paraplégie ne touche que les membres inférieurs.\\n\\nSource : ARTHROLOGIE COMPLET, vocabulaire ; Cours de chirurgie traumatique et digestif (pptx), Fractures du rachis, diapo 152\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le rachis cervical et le rachis lombaire comportent ensemble douze vertèbres\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le rachis compte 7 vertèbres cervicales et 5 lombaires : 7 + 5 = 12. (Il y a aussi 12 dorsales, 5 sacrées et 4 coccygiennes, soit 33 au total.)\\n\\nSource : Cours de chirurgie traumatique et digestif (pptx), Fractures du rachis, diapo 146 ; Neurochirurgie (fascicule), p. 12\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'échelle de Glasgow évalue l'ouverture des yeux, la réponse verbale et la réponse motrice\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le score de Glasgow cote l'ouverture des yeux (4 points), la réponse verbale (5 points) et la réponse motrice (6 points), soit un total de 3 à 15.\\n\\nSource : NEUROCHIRURGIE L3 (pptx), diapos 16-21\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Chez un traumatisé crânien, l'intervalle libre est la période séparant la perte de connaissance initiale de la réapparition secondaire des troubles de conscience\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'intervalle libre est le temps pendant lequel le blessé paraît s'améliorer après le traumatisme, avant une aggravation secondaire de la conscience ; c'est l'élément essentiel du diagnostic de l'hématome extradural. Remarque : le cours décrit l'intervalle libre comme le délai entre le traumatisme et l'apparition (ou la réapparition) des troubles ; il ne parle pas toujours d'une perte de connaissance initiale.\\n\\nSource : Cours de chirurgie traumatique et digestif (pptx), Traumatismes crâniens, diapos 110 et 112\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La ponction lombaire est contre-indiquée lorsqu'une hypertension intracrânienne avec risque d'engagement est suspectée\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"En cas d'hypertension intracrânienne (masse, hématome, œdème), la ponction lombaire est contre-indiquée : la baisse brutale de pression sous la lésion peut provoquer un engagement cérébral.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un liquide céphalorachidien hémorragique obtenu à la ponction lombaire confirme à lui seul la nature ischémique d'un accident vasculaire cérébral\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Un LCR hémorragique traduit une hémorragie méningée (ou un hématome intradural) : il ne peut pas confirmer un AVC ischémique, qui est au contraire un accident non hémorragique.\\n\\nSource : ANATOMIE LIVRE 2023-2024, méninges et LCR, p. 148 ; Cours de chirurgie traumatique et digestif (pptx), diapo 113\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une colostomie correspond à l'abouchement d'un segment du jéjunum à la peau\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La colostomie aboutit le côlon à la peau. L'abouchement du jéjunum à la peau est une jéjunostomie (celui de l'iléon, une iléostomie).\\n\\nSource : (explication hors cours du projet) ; voir Q6\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Après une chirurgie prostatique, une irrigation vésicale peut aider à prévenir l'obstruction de la sonde par des caillots\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Après adénomectomie prostatique, une irrigation (lavage vésical continu) passe dans la sonde ; on surveille le caillotage (douleurs vésicales, arrêt de l'écoulement = sonde bouchée), on accélère le débit si nécessaire et on fait des décaillotages.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Adénome de la prostate – interventions infirmières, p. 166-167\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__20\",\n       \"num\": \"21\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le lavement baryté est indiqué lorsqu'une perforation intestinale est suspectée\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Devant une perforation intestinale suspectée, le lavement baryté est contre-indiqué : la baryte pourrait passer dans le péritoine et entraîner une péritonite. Le cours le cite pour situer une occlusion (grêle ou côlon), pas en cas de perforation.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Occlusions – signes radiologiques, p. 125 (contre-indication : explication partiellement hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__21\",\n       \"num\": \"22\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une péritonite secondaire est liée à une lésion intra-abdominale responsable de la contamination péritonéale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les micro-organismes proviennent d'une atteinte du tube digestif (ulcère perforé, appendicite rompue…), des organes génitaux, ou d'une blessure : la péritonite secondaire est liée à une lésion intra-abdominale qui contamine le péritoine.\\n\\nSource : Cours de chirurgie traumatique et digestif (pptx), Péritonites – définition et étiologies, diapos 234-235\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__22\",\n       \"num\": \"23\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La contracture abdominale est le signe physique typique de l'occlusion intestinale simple\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans le syndrome occlusif, la paroi est souple ou à peine tendue : « il n'y a jamais de contracture malgré la distension gazeuse ». La contracture (ventre de bois) évoque une péritonite.\\n\\nSource : Cours de chirurgie traumatique et digestif (pptx), Occlusions intestinales aiguës, diapo 226\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__23\",\n       \"num\": \"24\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une occlusion mécanique par simple obstruction se définit nécessairement par l'écrasement ou la torsion des vaisseaux du mésentère\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"L'écrasement ou la torsion des vaisseaux du mésentère définissent la strangulation. L'obstruction (obturation) est un obstacle dans la lumière, la paroi ou extrinsèque, sans lésion vasculaire initiale.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Occlusions – étiologies, p. 121-122\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__24\",\n       \"num\": \"25\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans une occlusion du grêle, les vomissements apparaissent généralement plus précocement que dans une occlusion colique\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'occlusion du grêle donne des vomissements précoces, abondants, bilieux ; dans l'occlusion colique, les vomissements sont rares et tardifs.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Diagnostic du siège de l'occlusion, p. 125\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel signe physique est particulièrement évocateur d'une péritonite aiguë généralisée ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Contracture abdominale ou ventre de bois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Toux sèche\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Douleur du mollet\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Myosis\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Contracture abdominale ou ventre de bois\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La péritonite aiguë se traduit surtout par une contracture abdominale extensive réalisant au maximum le « ventre de bois ». La toux, la douleur du mollet et le myosis n'ont pas de lien avec la péritonite.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Contusions abdominales – tableau de péritonite par perforation, p. 91\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes, laquelle correspond le mieux à l'appendicite aiguë ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une urgence abdominale fréquente\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une maladie limitée au nourrisson\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une affection exclusivement féminine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une maladie toujours indolore\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Une urgence abdominale fréquente\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'appendicite aiguë est la plus fréquente des urgences abdominales, rare avant 3 ans, avec un pic entre 10 et 30 ans, et touche les deux sexes. Elle est douloureuse (fosse iliaque droite).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Appendicite aiguë – intérêt, p. 112\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Concernant la hernie crurale (fémorale), quelle proposition est correcte ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Elle ne s'étrangle jamais\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Son risque d'étranglement est relativement élevé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Elle siège dans le thorax\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Elle est toujours congénitale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Son risque d'étranglement est relativement élevé\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La hernie crurale, surtout chez la femme adulte, sort sous l'arcade crurale par un anneau étroit : son risque d'étranglement est élevé. Le cours rappelle de palper les orifices herniaires à la recherche d'une hernie étranglée (crurale) devant une occlusion.\\n\\nSource : Cours de chirurgie traumatique et digestif (pptx), Hernies (diapo 205) et Occlusions (diapo 226) ; risque élevé : explication partiellement hors cours du projet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel examen simple peut aider à mettre en évidence un globe vésical et à apprécier les reins, la vessie et la prostate ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Échographie uro-vésicale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Radiographie du crâne\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Électroencéphalogramme\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Fibroscopie bronchique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Échographie uro-vésicale\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'échographie (rein, vessie, prostate) est l'examen simple qui apprécie la rétention et le résidu post-mictionnel, le retentissement sur le haut appareil et le volume de la prostate.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Rétention urinaire, p. 172, et Adénome de la prostate, p. 163\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La fracture de Pouteau-Colles intéresse principalement\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'extrémité inférieure du radius\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'extrémité supérieure de l'ulna\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le col du fémur\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La clavicule\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. L'extrémité inférieure du radius\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La fracture de Pouteau-Colles est une fracture sus-articulaire de l'extrémité inférieure du radius, par hyperextension, environ 2 cm au-dessus de l'interligne radio-carpien.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Fractures du poignet, p. 37-38 ; Cours de chirurgie traumatique et digestif (pptx), diapo 57\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Sur les lieux d'un accident, devant une fracture suspectée d'un membre, le geste infirmier prioritaire est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Immobiliser provisoirement le membre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faire marcher le patient\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Masser le foyer de fracture\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Réaliser immédiatement une réduction forcée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Immobiliser provisoirement le membre\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Sur les lieux de l'accident, on immobilise les membres fracturés (gouttière ou attelles avec enveloppement ouaté). On ne fait pas marcher le blessé et on ne masse pas le foyer de fracture. La réduction relève du milieu hospitalier.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), CAT auprès d'un traumatisé des voies publiques – gestes salvateurs, p. 83\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le traitement orthopédique classique d'une fracture simple de la clavicule, on peut utiliser\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Un bandage en huit\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une sonde urinaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un plâtre pelvi-pédieux\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une traction crânienne\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Un bandage en huit\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Après réduction orthopédique, la contention se fait par un bandage en huit de chiffre (les branches se croisent dans le dos) ou une immobilisation coude au corps (Dujarrier, Velpeau).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Fracture de la clavicule, p. 15-16 ; Traumatologie complet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Selon la règle de Baxter (4 mL × poids × % de surface brûlée), quel volume faut-il perfuser durant les premières 24 h chez un patient de 58 kg brûlé à 27 %?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"3132 mL\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"6264 mL\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1566 mL\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1160 mL\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 6264 mL\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Calcul : 4 mL × 58 kg × 27 = 6 264 mL pour les 24 premières heures. Remarque : le cours L1 utilise la règle d'Evans (1 mL × poids × % de grosses molécules + la même quantité + 2000 mL de ration de base), pas la règle de Baxter. (Pathologie chirurgicale – Sémiologie L1 IDE-SF, p. 94)\\n\\nSource : Calcul à partir de la formule donnée dans l'énoncé\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour ce même patient, quelle quantité correspond approximativement à la moitié du volume calculé, à administrer durant les 8 premières heures ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"3132 mL\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"6264 mL\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"580 mL\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"2700 mL\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 3132 mL\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Moitié du volume : 6 264 ÷ 2 = 3 132 mL, à passer dans les 8 premières heures. Le cours précise aussi que « la moitié de la quantité totale doit être passée dans les 8 premières heures ».\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 IDE-SF, Brûlures – réanimation du premier jour, p. 94\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Avec une tubulure délivrant 20 gouttes/mL, quel débit faut-il régler pour perfuser 500 mL en 4 heures ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Environ 20 gouttes/min\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Environ 80 gouttes/min\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Environ 42 gouttes/min\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Environ 120 gouttes/min\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Environ 42 gouttes/min\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Débit (gouttes/min) = volume (mL) × 20 ÷ durée (min) = 500 × 20 ÷ 240 = 10 000 ÷ 240 ≈ 41,7, soit environ 42 gouttes/min. Remarque : dans le sujet, les options sont dans l'ordre B, C, A, D.\\n\\nSource : (calcul ; explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Avec une tubulure délivrant 20 gouttes/mL, quel débit faut-il régler pour perfuser 500 mL en 3 h 15 min ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Environ 51 gouttes/min\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Environ 25 gouttes/min\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Environ 75 gouttes/min\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Environ 100 gouttes/min\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Environ 51 gouttes/min\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"3 h 15 min = 195 min. Débit = 500 × 20 ÷ 195 = 10 000 ÷ 195 ≈ 51,3, soit environ 51 gouttes/min.\\n\\nSource : (calcul ; explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Avec une tubulure délivrant 20 gouttes/mL, quel débit permet de perfuser 6 litres en 24 heures ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Environ 84 gouttes/min\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Environ 42 gouttes/min\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Environ 25 gouttes/min\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Environ 150 gouttes/min\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Environ 84 gouttes/min\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"6 L = 6 000 mL ; 24 h = 1 440 min. Débit = 6 000 × 20 ÷ 1 440 ≈ 83,3 gouttes/min, soit environ 83-84 gouttes/min. Remarque : le résultat exact est 83,3 ; la réponse retenue (≈ 84) est un arrondi.\\n\\nSource : (calcul ; explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quel est l'ordre physiopathologique le plus logique au cours d'une brûlure étendue ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hypovolémie → exsudation → trouble capillaire → anoxie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Anoxie → hypovolémie → exsudation → trouble capillaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Trouble de la perméabilité capillaire → exsudation plasmatique → hypovolémie → anoxie tissulaire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Exsudation → anoxie → trouble capillaire → hypovolémie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Trouble de la perméabilité capillaire → exsudation plasmatique → hypovolémie → anoxie tissulaire\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La brûlure étendue altère la perméabilité capillaire, d'où une exsudation plasmatique (pertes et œdème), puis une hypovolémie (choc) et, si elle n'est pas compensée, une anoxie tissulaire (rein : anurie). Remarque : le cours commence par l'exsudation plasmatique et décrit un cercle vicieux (l'anoxie aggrave les troubles de la perméabilité capillaire) ; l'ordre retenu reste cohérent avec ce mécanisme.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 IDE-SF, Brûlures – physiopathologie, période initiale, p. 87\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelles localisations rendent une brûlure particulièrement préoccupante ? (3 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Face\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Mains\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Périnée et organes génitaux\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Cheveux uniquement\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Ongles uniquement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Face ; B. Mains ; C. Périnée et organes génitaux\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Le cours cite comme critères de gravité par la localisation : mains, visage, articulations, orifices naturels, périnée. La face menace les yeux et les voies respiratoires ; les parties génitales entraînent sténoses et séquelles graves. Les cheveux ou les ongles seuls ne sont pas des localisations graves.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 IDE-SF, Brûlures – localisation et critères de gravité, p. 86 et 99\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les organes suivants, lesquels sont des organes creux abdomino-pelviens ? (2 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vessie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Côlon\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Foie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Rate\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Pancréas\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Vessie ; B. Côlon\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"Les organes creux sont la vessie et le côlon (tube digestif). Le foie, la rate et le pancréas sont des organes pleins (viscères pleins, glandes annexes).\\n\\nSource : Traumatologie complet, examen du traumatisé (viscères pleins / creux) ; PDF APPAREIL DIGESTIF L1\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__40\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'embarrure crânienne correspond le mieux à\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une fracture de la voûte avec enfoncement d'un fragment osseux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une simple plaie du cuir chevelu\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une entorse cervicale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une fracture de la clavicule\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Une fracture de la voûte avec enfoncement d'un fragment osseux\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les fractures de la voûte crânienne peuvent être simples ou avec embarrure, c'est-à-dire avec enfoncement d'un fragment osseux vers l'intérieur du crâne.\\n\\nSource : Cours de chirurgie traumatique et digestif (pptx), Traumatismes crâniens – lésions osseuses, diapo 108\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__41\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Qu'est-ce qui distingue surtout un polytraumatisé d'un patient simplement polyfracturé ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La présence de lésions multiples dont au moins une peut engager le pronostic vital\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La présence obligatoire de trois fractures\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'absence de toute lésion viscérale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'âge supérieur à 60 ans\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La présence de lésions multiples dont au moins une peut engager le pronostic vital\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le polytraumatisé a plusieurs lésions dont au moins une engage le pronostic vital ; à ne pas confondre avec le polyfracturé. Il n'existe pas de nombre minimal de fractures ni de critère d'âge.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Le polytraumatisé, p. 86\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__42\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Avant de démarrer une transfusion sanguine, quelles vérifications sont essentielles ? (3 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Identité du patient et prescription\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Concordance et compatibilité du produit sanguin\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Date de péremption et intégrité de la poche\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Couleur des chaussures du patient\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Groupe sanguin d'un membre de la famille\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Identité du patient et prescription ; B. Concordance et compatibilité du produit sanguin ; C. Date de péremption et intégrité de la poche\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Avant toute transfusion, on vérifie l'identité du patient et la prescription, la concordance et la compatibilité du produit avec le groupe du receveur (contrôle ultime au lit), la date de péremption et l'intégrité de la poche. Le groupe d'un membre de la famille ne remplace pas celui du patient.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__43\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nursing d'un patient alité comprend notamment\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La toilette et la prévention des escarres\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La prescription d'antibiotiques\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La réduction d'une fracture\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La réalisation d'une anesthésie générale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La toilette et la prévention des escarres\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le nursing du patient alité comprend notamment la toilette et la prévention des escarres, la surveillance des paramètres et de l'état général. La prescription, la réduction d'une fracture et l'anesthésie ne sont pas des actes de nursing.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Fractures – rôle de l'infirmier (nursing), p. 36 ; Traumatologie complet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__44\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Chez un malade en décubitus latéral, quels sont deux points d'appui particulièrement exposés aux escarres ? (2 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Grand trochanter\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Malléole externe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Paume de la main\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Nombril\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Pavillon de l'oreille uniquement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Grand trochanter ; B. Malléole externe\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"En décubitus latéral, l'appui se fait sur le côté : grand trochanter, malléole externe, mais aussi épaule, oreille et face latérale du genou. La paume de la main et le nombril ne sont pas des points d'appui. Remarque : l'option E dit « pavillon de l'oreille uniquement » ; l'oreille est un point d'appui en décubitus latéral, mais le mot « uniquement » rend la proposition fausse.\\n\\nSource : (explication hors cours du projet) ; le cours cite la surveillance des points d'appui et le changement de position (Neurochirurgie p. 21 ; TSI p. 67)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__45\",\n       \"num\": \"46\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 : HERNIE INGUINALE ÉTRANGLÉE Un patient de 45 ans se présente pour une douleur vive de l'aine droite. Il explique que, depuis plusieurs mois, une tuméfaction apparaissait à l'effort, disparaissait lorsqu'il se couchait et était habituellement indolore. Depuis quelques heures, la masse est devenue douloureuse, dure, irréductible et non impulsive à la toux. Il présente également des nausées et des vomissements.\",\n       \"text\": \"Quelle affection était probablement présente avant l'épisode douloureux actuel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hernie inguinale simple\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Péritonite\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Appendicite aiguë\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hydrocèle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Hernie inguinale simple\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Avant l'épisode, la tuméfaction apparaissait à l'effort, disparaissait couché et était indolore : ce sont les caractères d'une hernie inguinale simple, réductible et non compliquée.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Hernies – hernie non compliquée, p. 107\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__46\",\n       \"num\": \"47\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 : HERNIE INGUINALE ÉTRANGLÉE Un patient de 45 ans se présente pour une douleur vive de l'aine droite. Il explique que, depuis plusieurs mois, une tuméfaction apparaissait à l'effort, disparaissait lorsqu'il se couchait et était habituellement indolore. Depuis quelques heures, la masse est devenue douloureuse, dure, irréductible et non impulsive à la toux. Il présente également des nausées et des vomissements.\",\n       \"text\": \"Quels éléments de l'histoire évoquent une hernie réductible avant la complication ? (2 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Tuméfaction habituellement indolore\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Disparition de la tuméfaction en position couchée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Contracture abdominale permanente\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hématurie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Tuméfaction habituellement indolore ; B. Disparition de la tuméfaction en position couchée\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"Une hernie non compliquée est une tuméfaction indolore qui se réintègre spontanément en position couchée (réductibilité) et est impulsive à la toux.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Hernies, p. 107 ; Cours de chirurgie traumatique et digestif (pptx), diapo 202\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__47\",\n       \"num\": \"48\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 : HERNIE INGUINALE ÉTRANGLÉE Un patient de 45 ans se présente pour une douleur vive de l'aine droite. Il explique que, depuis plusieurs mois, une tuméfaction apparaissait à l'effort, disparaissait lorsqu'il se couchait et était habituellement indolore. Depuis quelques heures, la masse est devenue douloureuse, dure, irréductible et non impulsive à la toux. Il présente également des nausées et des vomissements.\",\n       \"text\": \"Quel est le diagnostic le plus probable au moment de l'admission ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hernie inguinale étranglée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hernie hiatale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Appendicite chronique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Cystite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Hernie inguinale étranglée\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Une douleur vive, une masse devenue dure, irréductible et non impulsive, avec nausées et vomissements : c'est le tableau de l'étranglement herniaire, une urgence chirurgicale.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Étranglement herniaire, p. 107-108\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__48\",\n       \"num\": \"49\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 : HERNIE INGUINALE ÉTRANGLÉE Un patient de 45 ans se présente pour une douleur vive de l'aine droite. Il explique que, depuis plusieurs mois, une tuméfaction apparaissait à l'effort, disparaissait lorsqu'il se couchait et était habituellement indolore. Depuis quelques heures, la masse est devenue douloureuse, dure, irréductible et non impulsive à la toux. Il présente également des nausées et des vomissements.\",\n       \"text\": \"Quels caractères de la masse sont en faveur de l'étranglement ? (3 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Dure\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Irréductible\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Non impulsive à la toux\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Toujours indolore\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Disparaît immédiatement au repos\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Dure ; B. Irréductible ; C. Non impulsive à la toux\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"La masse étranglée est dure, tendue, douloureuse, irréductible et non impulsive à la toux. « Toujours indolore » et « disparaît au repos » décrivent au contraire la hernie simple.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), p. 108\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__49\",\n       \"num\": \"50\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 : HERNIE INGUINALE ÉTRANGLÉE Un patient de 45 ans se présente pour une douleur vive de l'aine droite. Il explique que, depuis plusieurs mois, une tuméfaction apparaissait à l'effort, disparaissait lorsqu'il se couchait et était habituellement indolore. Depuis quelques heures, la masse est devenue douloureuse, dure, irréductible et non impulsive à la toux. Il présente également des nausées et des vomissements.\",\n       \"text\": \"En cas de retard de prise en charge, quelle complication locale grave peut survenir ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Nécrose ischémique de l'anse étranglée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Otite moyenne\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fracture du fémur\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Conjonctivite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Nécrose ischémique de l'anse étranglée\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'étranglement est une striction permanente au collet qui fait souffrir les vaisseaux : ischémie, sphacèle (nécrose) puis perforation du viscère hernié. Si l'anse est nécrosée, on la résèque.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Étranglement herniaire et traitement, p. 107-109\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__50\",\n       \"num\": \"51\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2 : PÉRITONITE AIGUË Aux urgences chirurgicales, vous recevez un homme de 26 ans pour douleur abdominale brutale « en coup de poignard », nausées, vomissements et fièvre à 39,5 °C. La pression artérielle est à 90/50 mmHg et le pouls à 110/min. À la palpation, l'abdomen est très douloureux avec une contracture diffuse dite « ventre de bois ».\",\n       \"text\": \"Quel diagnostic évoquez-vous en priorité ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Péritonite aiguë généralisée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Entorse de cheville\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Sinusite\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hydrocèle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Péritonite aiguë généralisée\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Une douleur brutale « en coup de poignard », de la fièvre, une hypotension avec tachycardie et une contracture diffuse en « ventre de bois » forment le tableau de la péritonite aiguë généralisée (urgence abdominale).\\n\\nSource : Cours de chirurgie traumatique et digestif (pptx), Péritonites, diapo 236 ; Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), p. 91\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__51\",\n       \"num\": \"52\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2 : PÉRITONITE AIGUË Aux urgences chirurgicales, vous recevez un homme de 26 ans pour douleur abdominale brutale « en coup de poignard », nausées, vomissements et fièvre à 39,5 °C. La pression artérielle est à 90/50 mmHg et le pouls à 110/min. À la palpation, l'abdomen est très douloureux avec une contracture diffuse dite « ventre de bois ».\",\n       \"text\": \"Quelles affections peuvent provoquer une péritonite secondaire ? (2 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ulcère gastro-duodénal perforé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Appendicite perforée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Myopie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Rhinite allergique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Ulcère gastro-duodénal perforé ; B. Appendicite perforée ; C. Myopie\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Les causes les plus courantes de la péritonite secondaire sont les ulcères gastro-duodénaux (perforés), l'appendicite rompue, la diverticulite, la cholécystite, la pancréatite aiguë, la salpingite… La myopie et la rhinite allergique n'ont aucun lien avec le péritoine.\\n\\nSource : Cours de chirurgie traumatique et digestif (pptx), Péritonites – étiologies, diapo 235\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__52\",\n       \"num\": \"53\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2 : PÉRITONITE AIGUË Aux urgences chirurgicales, vous recevez un homme de 26 ans pour douleur abdominale brutale « en coup de poignard », nausées, vomissements et fièvre à 39,5 °C. La pression artérielle est à 90/50 mmHg et le pouls à 110/min. À la palpation, l'abdomen est très douloureux avec une contracture diffuse dite « ventre de bois ».\",\n       \"text\": \"Quel signe physique renforce le diagnostic de péritonite ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Contracture abdominale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Pâleur conjonctivale isolée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Myosis\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Douleur de l'épaule\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Contracture abdominale\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La contracture abdominale (défense généralisée, ventre de bois) est le signe physique majeur de la péritonite. La pâleur conjonctivale isolée, le myosis et la douleur de l'épaule ne sont pas spécifiques.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), p. 91 ; Cours de chirurgie traumatique et digestif (pptx), diapo 236\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__53\",\n       \"num\": \"54\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2 : PÉRITONITE AIGUË Aux urgences chirurgicales, vous recevez un homme de 26 ans pour douleur abdominale brutale « en coup de poignard », nausées, vomissements et fièvre à 39,5 °C. La pression artérielle est à 90/50 mmHg et le pouls à 110/min. À la palpation, l'abdomen est très douloureux avec une contracture diffuse dite « ventre de bois ».\",\n       \"text\": \"Avant l'arrivée du médecin, quelles actions infirmières immédiates sont appropriées ? (3 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Accueillir et installer le patient\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Prendre les constantes vitales\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Prévoir un récipient en cas de vomissements\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Faire manger le patient\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Annoncer un diagnostic définitif au patient sans avis médical\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Accueillir et installer le patient ; B. Prendre les constantes vitales ; C. Prévoir un récipient en cas de vomissements\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Avant l'arrivée du médecin, l'infirmier accueille et installe le patient, prend les constantes (pouls, TA, température) et prévient les vomissements. Le patient doit rester à jeun et l'infirmier n'annonce pas de diagnostic.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Péritonite – interventions infirmières, p. 133\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__54\",\n       \"num\": \"55\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2 : PÉRITONITE AIGUË Aux urgences chirurgicales, vous recevez un homme de 26 ans pour douleur abdominale brutale « en coup de poignard », nausées, vomissements et fièvre à 39,5 °C. La pression artérielle est à 90/50 mmHg et le pouls à 110/min. À la palpation, l'abdomen est très douloureux avec une contracture diffuse dite « ventre de bois ».\",\n       \"text\": \"Quels éléments peuvent faire partie de la prise en charge initiale prescrite d'une péritonite ? (4 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Réanimation hydro-électrolytique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Antibiothérapie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Aspiration digestive par sonde si indiquée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Traitement chirurgical de la cause\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Alimentation orale immédiate\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Réanimation hydro-électrolytique ; B. Antibiothérapie ; C. Aspiration digestive par sonde si indiquée ; D. Traitement chirurgical de la cause\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Le traitement médical prépare rapidement le patient à l'intervention : aspiration gastrique, correction des déséquilibres hydro-électrolytiques et antibiothérapie à large spectre. Ensuite, laparotomie pour traiter la cause. Pas d'alimentation orale (patient à jeun).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Péritonite – traitement, p. 133\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__55\",\n       \"num\": \"56\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°3 : OCCLUSION AIGUË DU GRÊLE Un homme de 68 ans est admis pour douleurs abdominales, vomissements répétés, arrêt des matières et des gaz et distension abdominale. Une radiographie de l'abdomen sans préparation montre plusieurs niveaux hydro-aériques centraux. Le chirurgien retient le diagnostic d'occlusion aiguë du grêle.\",\n       \"text\": \"Quel diagnostic est le plus compatible avec ce tableau ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Occlusion aiguë du grêle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Cystite simple\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pneumonie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Fracture du radius\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Occlusion aiguë du grêle\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les douleurs, les vomissements répétés, l'arrêt des matières et des gaz, la distension et les niveaux hydro-aériques centraux à l'ASP orientent vers une occlusion aiguë du grêle.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Occlusions, p. 125\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__56\",\n       \"num\": \"57\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°3 : OCCLUSION AIGUË DU GRÊLE Un homme de 68 ans est admis pour douleurs abdominales, vomissements répétés, arrêt des matières et des gaz et distension abdominale. Une radiographie de l'abdomen sans préparation montre plusieurs niveaux hydro-aériques centraux. Le chirurgien retient le diagnostic d'occlusion aiguë du grêle.\",\n       \"text\": \"Quels sont les quatre signes essentiels du syndrome occlusif présents ou attendus ? (4 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Douleurs abdominales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Vomissements\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Arrêt des matières et des gaz\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Météorisme abdominal\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Hémoptysie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Douleurs abdominales ; B. Vomissements ; C. Arrêt des matières et des gaz ; D. Météorisme abdominal\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Le syndrome occlusif comporte 4 symptômes essentiels : 3 signes fonctionnels (douleurs abdominales, vomissements, arrêt des matières et des gaz) et 1 signe physique (météorisme abdominal). L'hémoptysie n'en fait pas partie.\\n\\nSource : Cours de chirurgie traumatique et digestif (pptx), Syndrome occlusif, diapos 225-226\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__57\",\n       \"num\": \"58\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°3 : OCCLUSION AIGUË DU GRÊLE Un homme de 68 ans est admis pour douleurs abdominales, vomissements répétés, arrêt des matières et des gaz et distension abdominale. Une radiographie de l'abdomen sans préparation montre plusieurs niveaux hydro-aériques centraux. Le chirurgien retient le diagnostic d'occlusion aiguë du grêle.\",\n       \"text\": \"Quels sont les trois signes fonctionnels classiques de l'occlusion ? (3 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Douleur abdominale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Vomissements\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Arrêt des matières et des gaz\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Météorisme observé à l'examen\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Hyperleucocytose\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Douleur abdominale ; B. Vomissements ; C. Arrêt des matières et des gaz\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Les 3 signes fonctionnels sont la douleur, les vomissements et l'arrêt des matières et des gaz. Le météorisme est un signe physique ; l'hyperleucocytose est un signe biologique.\\n\\nSource : Cours de chirurgie traumatique et digestif (pptx), diapos 225-227\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__58\",\n       \"num\": \"59\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°3 : OCCLUSION AIGUË DU GRÊLE Un homme de 68 ans est admis pour douleurs abdominales, vomissements répétés, arrêt des matières et des gaz et distension abdominale. Une radiographie de l'abdomen sans préparation montre plusieurs niveaux hydro-aériques centraux. Le chirurgien retient le diagnostic d'occlusion aiguë du grêle.\",\n       \"text\": \"Les niveaux hydro-aériques centraux et multiples orientent vers une occlusion\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Du grêle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Du côlon distal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"De l'œsophage\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"De la vessie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Du grêle\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans l'occlusion du grêle, les images hydro-aériques sont centrales, multiples, plus hautes que larges ; dans l'occlusion colique, elles sont périphériques et dessinent le cadre colique.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Diagnostic du siège de l'occlusion, p. 125-126\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j5-ide__59\",\n       \"num\": \"60\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°3 : OCCLUSION AIGUË DU GRÊLE Un homme de 68 ans est admis pour douleurs abdominales, vomissements répétés, arrêt des matières et des gaz et distension abdominale. Une radiographie de l'abdomen sans préparation montre plusieurs niveaux hydro-aériques centraux. Le chirurgien retient le diagnostic d'occlusion aiguë du grêle.\",\n       \"text\": \"Quels sont deux objectifs majeurs de la prise en charge d'une occlusion mécanique ? (2 réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Corriger les désordres hydro-électrolytiques\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Lever l'obstacle\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Donner systématiquement à manger\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Faire marcher le patient pour débloquer l'intestin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Corriger les désordres hydro-électrolytiques ; B. Lever l'obstacle\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"Le traitement des occlusions comporte une double action : la correction des déséquilibres humoraux (hydro-électrolytiques) et la suppression de l'obstacle. On ne fait pas manger le patient (aspiration digestive, perfusion).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales – L2 IDE 2025 (licence 2 ide.pdf), Occlusions – traitement, p. 126\",\n       \"sourceDoc\": \"Prépa D.E — J5 Chirurgie IDE (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Chirurgie_IDE_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
